159: template <char delimiter, typename SubParser>
160: auto delimited(SubParser& subParser) -> decltype(auto) {
161:   // Create a parser that parses several instances of subParser separated by the given delimiter.
162: 
163:   typedef p::OutputType<SubParser, Input> Element;
164:   return p::transform(p::sequence(subParser,
165:       p::many(p::sequence(p::exactChar<delimiter>(), subParser))),
166:       [](Element&& first, kj::Array<Element>&& rest) {
167:     auto result = kj::heapArrayBuilder<Element>(rest.size() + 1);
168:     result.add(kj::mv(first));
169:     for (auto& e: rest) result.add(kj::mv(e));
170:     return result.finish();
